import json

def write(pairs: list[tuple[str, str]], path: str = "{{output_path}}"):
    with open(path, "w") as f:
        for q, a in pairs:
            row = {"messages": [
                {"role": "user", "content": q},
                {"role": "assistant", "content": a},
            ]}
            f.write(json.dumps(row, ensure_ascii=False) + "\n")

if __name__ == "__main__":
    write([("hi", "hello"), ("bye", "goodbye")])
